<?php
namespace App\Console\Commands;
use Illuminate\Console\Command;
use Illuminate\Support\Facades\Storage;
final class EstafetaConfigTemplateCommand extends Command { protected $signature='zigo:estafeta-config-template {--environment=stage}';protected $description='Genera plantilla privada y redactada de configuración Estafeta.';public function handle():int{$environment=strtolower((string)$this->option('environment'));if($environment!=='stage'){$this->error('Solo se permite --environment=stage en esta fase.');return self::INVALID;}$vars=['ZIGO_ESTAFETA_ENVIRONMENT'=>['required',config('zigo_estafeta.environment'),'Ambiente'],'ZIGO_ESTAFETA_AUTH_URL'=>['required',config('zigo_estafeta.auth_url'),'Base OAuth confirmada'],'ZIGO_ESTAFETA_AUTH_PATH'=>['required',config('zigo_estafeta.auth_path'),'Ruta OAuth confirmada'],'ZIGO_ESTAFETA_CLIENT_ID'=>['required',config('zigo_estafeta.client_id'),'OAuth client id'],'ZIGO_ESTAFETA_CLIENT_SECRET'=>['required',config('zigo_estafeta.client_secret'),'OAuth client secret'],'ZIGO_ESTAFETA_SCOPE'=>['required',config('zigo_estafeta.scope'),'OAuth scope'],'ZIGO_ESTAFETA_COVERAGE_URL'=>['required',config('zigo_estafeta.coverage_url'),'Pendiente contrato confirmado'],'ZIGO_ESTAFETA_QUOTE_URL'=>['required',config('zigo_estafeta.quote_url'),'Pendiente contrato confirmado'],'ZIGO_ESTAFETA_GATEWAY_ENABLED'=>['optional',config('zigo_estafeta.gateway_enabled'),'Activa gateway B2C'],'ZIGO_ESTAFETA_FALLBACK_LEGACY'=>['optional',config('zigo_estafeta.fallback_legacy'),'Fallback explícito']];$rows=[];foreach($vars as $name=>$v)$rows[]=['variable'=>$name,'requirement'=>$v[0],'description'=>$v[2],'status'=>filled($v[1])?'configured':'missing'];$path='private/estafeta-config-templates/stage-'.now()->format('Ymd-His').'.json';Storage::disk('local')->put($path,json_encode(['environment'=>'stage','variables'=>$rows],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$this->info('Plantilla: storage/app/'.$path);return self::SUCCESS;} }
